30	export function createApp(store = createScenarioStore()) {
31	  function isJsonContentType(request) {
32	    const contentType = request.headers["content-type"];
33	    if (typeof contentType !== "string") {
34	      return false;
35	    }
36	    const mediaType = contentType.split(";")[0].trim().toLowerCase();
37	    return mediaType === "application/json";
38	  }
39	
40	  function readBody(request) {
41	    return new Promise((resolve, reject) => {
42	      const chunks = [];
43	      let size = 0;
44	      request.on("data", chunk => {
45	        chunks.push(chunk);
46	        size += chunk.length;
47	      });
48	      request.on("end", () => resolve(Buffer.concat(chunks, size).toString("utf8")));
49	      request.on("error", reject);
50	    });
51	  }
52	
53	  async function readJsonObject(request, response) {
54	    if (!isJsonContentType(request)) {
55	      badRequest(response, "Content-Type must be application/json");
56	      return null;
57	    }
58	
