async function fetchAllEventPages(baseUrl, id, initialQuery = "") {
  const seen = [];
  let query = initialQuery;
  let pages = 0;
  for (;;) {
    const page = await requestJson(baseUrl, `/scenarios/${id}/events${query}`);
    assert.equal(page.status, 200);
    pages += 1;
    seen.push(...page.body.events);
    if (page.body.nextCursor === null) {
      break;
    }
    const separator = query.includes("?") ? "&" : "?";
    query = `${query}${separator}cursor=${encodeURIComponent(page.body.nextCursor)}`;
    if (pages > 1000) {
      throw new Error("pagination did not terminate");
    }
  }
  return { events: seen, pages };
}

